//
// REN 01 · REN 02 · REN 04 · REN 05 (UI) — Plano_de_Testes_QA_MatchWallet.md §7 (docs-test/areas/ren.md).
// Fórmulas e limites numéricos pertencem ao backend (ver `real/rentabilidade-servidor`); aqui
// validamos o que a tela controla: payload numérico na escala certa, prévia igual à coluna
// "% do CDI", entradas recusadas antes do envio e o tratamento de duplicidade/repetição.

const CARTEIRA_ID = 'cart-1'

const DETALHE = {
  id: CARTEIRA_ID,
  nome: 'Carteira Moderada',
  perfilAlvo: 'MODERADO',
  descricao: null,
  ativa: true,
  criadoEm: '2026-01-01T00:00:00.000Z',
  versaoAtual: null,
}

interface Linha {
  mesReferencia: string
  rentabilidade: number
  cdi: number
  ibov: number
  percentualCdi: number | null
}

interface Corpo {
  mesReferencia: string
  rentabilidadeMes: number
  rentabilidadeAcumuladaAno: number
  cdiMes: number
  ibovMes: number
}

/**
 * "Servidor" com estado: o POST grava na série (409 se a competência já existe, 400 se o mês é
 * inválido, como o backend) e o próximo GET do histórico já traz a linha. `atrasoPost` mantém o
 * envio em voo para testar clique repetido.
 */
function prepararServidor(serie: Linha[], atrasoPost = 0) {
  cy.bloquearApi()
  cy.stubSessao('admin')
  cy.stubApi('GET', `/carteiras/${CARTEIRA_ID}`, DETALHE, 'detalhe')
  cy.stubApi(
    'GET',
    `/carteiras/${CARTEIRA_ID}/versoes*`,
    { items: [], total: 0, page: 1, pageSize: 100 },
    'versoes',
  )
  cy.intercept('GET', `**/api/v1/carteiras/${CARTEIRA_ID}/historico-performance*`, (req) => {
    req.reply({
      carteiraId: CARTEIRA_ID,
      carteiraNome: DETALHE.nome,
      serie,
      acumulado: { carteira: 0, cdi: 0, ibov: 0 },
    })
  }).as('historico')
  cy.intercept('POST', `**/api/v1/carteiras/${CARTEIRA_ID}/rentabilidade`, (req) => {
    const corpo = req.body as Corpo

    if (!/^\d{4}-(0[1-9]|1[0-2])$/.test(corpo.mesReferencia)) {
      req.reply({
        statusCode: 400,
        delay: atrasoPost,
        body: {
          error: {
            code: 'VALIDATION_ERROR',
            message: 'mesReferencia deve estar no formato YYYY-MM.',
          },
        },
      })
      return
    }
    if (serie.some((l) => l.mesReferencia === corpo.mesReferencia)) {
      req.reply({
        statusCode: 409,
        delay: atrasoPost,
        body: {
          error: {
            code: 'CONFLICT',
            message: 'Já existe lançamento de rentabilidade para esta carteira nesta competência.',
          },
        },
      })
      return
    }

    serie.push({
      mesReferencia: corpo.mesReferencia,
      rentabilidade: corpo.rentabilidadeMes,
      cdi: corpo.cdiMes,
      ibov: corpo.ibovMes,
      percentualCdi: corpo.cdiMes === 0 ? null : (corpo.rentabilidadeMes / corpo.cdiMes) * 100,
    })
    req.reply({
      statusCode: 201,
      body: { id: 'r', carteiraId: CARTEIRA_ID, ...corpo },
      delay: atrasoPost,
    })
  }).as('lancar')

  cy.visit(`/admin/carteiras/${CARTEIRA_ID}`)
  cy.wait(['@detalhe', '@versoes'])
  cy.contains('[role="tab"]', 'Rentabilidade').click()
  cy.wait('@historico')
}

function abrirFormulario() {
  cy.get('[data-cy="rentab-lancar"]').click()
  cy.get('[data-cy="rentab-competencia"]').should('be.visible')
}

function preencher(
  campos: Partial<Record<'competencia' | 'carteira' | 'acumulado' | 'cdi' | 'ibov', string>>,
) {
  const alvo = {
    competencia: 'rentab-competencia',
    carteira: 'rentab-carteira',
    acumulado: 'rentab-acumulado',
    cdi: 'rentab-cdi',
    ibov: 'rentab-ibov',
  } as const

  for (const [campo, valor] of Object.entries(campos)) {
    const seletor = `[data-cy="${alvo[campo as keyof typeof alvo]}"]`
    cy.get(seletor).clear()
    if (valor) cy.get(seletor).type(valor)
  }
}

function salvar() {
  cy.get('[data-cy="rentab-submit"]').click()
}

/** Células da linha de uma competência (ordem: competência, carteira, CDI, Ibovespa, % do CDI). */
function celulas(indiceLinha = 0) {
  return cy.get('[data-cy="rentab-linha"]').eq(indiceLinha).find('td')
}

describe('Plano QA · Lançamento de rentabilidade (UI)', () => {
  it('REN 01 · lança carteira 1,50 / acumulado 6,25 / CDI 1,00 / Ibov -2,00 e recarrega → payload na escala certa e valores persistidos sem virar 150%', () => {
    const serie: Linha[] = []
    prepararServidor(serie)

    abrirFormulario()
    preencher({ competencia: '2026-09', carteira: '1.5', acumulado: '6.25', cdi: '1', ibov: '-2' })
    salvar()

    // Números (não texto) e na mesma escala digitada: 1,5 é 1,5 — não 0,015 nem 150.
    cy.wait('@lancar').its('request.body').should('deep.equal', {
      mesReferencia: '2026-09',
      rentabilidadeMes: 1.5,
      rentabilidadeAcumuladaAno: 6.25,
      cdiMes: 1,
      ibovMes: -2,
    })
    cy.contains('Rentabilidade de 2026-09 lançada').should('be.visible')

    cy.reload()
    cy.contains('[role="tab"]', 'Rentabilidade').click()
    cy.get('[data-cy="rentab-linha"]').should('have.length', 1)
    celulas().eq(0).should('contain.text', '2026')
    celulas().eq(1).should('have.text', '+1,50 %').and('not.contain.text', '150')
    celulas().eq(2).should('have.text', '+1,00 %')
    celulas().eq(3).should('have.text', '-2,00 %')
  })

  it('REN 02 · prévia e coluna "% do CDI" → mesmos 150,0 % para 1,50 ÷ 1,00 e mesmo arredondamento em 1 ÷ 3', () => {
    const serie: Linha[] = []
    prepararServidor(serie)

    abrirFormulario()
    // Sem CDI não há prévia calculada: traço, nunca um número.
    cy.get('[data-cy="rentab-previa"]').should('have.text', '—')

    preencher({ competencia: '2026-08', carteira: '1.5', acumulado: '1.5', cdi: '1', ibov: '0.5' })
    cy.get('[data-cy="rentab-previa"]').should('have.text', '150,0 %')
    salvar()
    cy.wait('@lancar')
    cy.wait('@historico')

    // Segundo lançamento com dízima: a prévia e a coluna arredondam igual.
    abrirFormulario()
    preencher({ competencia: '2026-09', carteira: '1', acumulado: '2.5', cdi: '3', ibov: '0.5' })
    cy.get('[data-cy="rentab-previa"]')
      .invoke('text')
      .then((previa) => {
        expect(previa.trim()).to.eq('33,3 %')
        salvar()
        cy.wait('@lancar')
        cy.wait('@historico')
        cy.get('[data-cy="rentab-linha"]').should('have.length', 2)
        celulas(0).eq(4).should('have.text', '150,0 %')
        celulas(1).eq(4).invoke('text').should('eq', previa.trim())
      })
  })

  it('REN 04 · negativo, zero, casas extras, letras e vírgula → aceitos e recusados com clareza, sem converter em silêncio', () => {
    const serie: Linha[] = []
    prepararServidor(serie)

    // Negativo e zero valem como número (0 não é "vazio").
    const aceitos = [
      { mes: '2026-01', valor: '-0.5', esperado: -0.5 },
      { mes: '2026-02', valor: '0', esperado: 0 },
      { mes: '2026-03', valor: '1.25', esperado: 1.25 },
    ]
    for (const { mes, valor, esperado } of aceitos) {
      abrirFormulario()
      preencher({ competencia: mes, carteira: valor, acumulado: valor, cdi: '1', ibov: '0' })
      salvar()
      cy.wait('@lancar').its('request.body.rentabilidadeMes').should('eq', esperado)
      cy.get('[data-cy="rentab-competencia"]').should('not.exist')
    }

    // Casas decimais além do passo (0,01): o navegador barra o envio.
    abrirFormulario()
    preencher({ competencia: '2026-04', carteira: '1.234', acumulado: '1', cdi: '1', ibov: '0' })
    salvar()
    cy.get('[data-cy="rentab-carteira"]').then(($campo) => {
      expect(($campo[0] as HTMLInputElement).validity.stepMismatch, 'stepMismatch').to.eq(true)
    })

    // Letras não entram em campo numérico: o campo fica vazio e a obrigatoriedade aparece.
    cy.get('[data-cy="rentab-carteira"]').clear().type('abc')
    cy.get('[data-cy="rentab-carteira"]').should('have.value', '')
    salvar()
    cy.contains('Informe a rentabilidade do mês').should('be.visible')

    // Vírgula: ou é rejeitada (campo vazio) ou vale 1,5 — jamais vira 15.
    cy.get('[data-cy="rentab-carteira"]').clear().type('1,5')
    cy.get('[data-cy="rentab-carteira"]')
      .invoke('val')
      .should((valor) => {
        expect(['', '1.5', '1,5']).to.include(valor)
      })
    cy.get('@lancar.all').should('have.length', 3)
    cy.get('@lancar.all').each((chamada) => {
      const { rentabilidadeMes } = (chamada as unknown as { request: { body: Corpo } }).request.body
      expect(rentabilidadeMes).not.to.eq(15)
    })
  })

  it('REN 05 · competência vazia, malformada, mês 13, duplicada, cancelada e com clique duplo → regra clara, nenhuma linha ambígua', () => {
    const serie: Linha[] = [
      { mesReferencia: '2026-08', rentabilidade: 2, cdi: 1, ibov: 0.5, percentualCdi: 200 },
    ]
    prepararServidor(serie, 400)

    const valores = { carteira: '1', acumulado: '1', cdi: '1', ibov: '0' }

    abrirFormulario()
    // Vazia e malformadas: barradas na tela, sem envio.
    preencher({ competencia: '', ...valores })
    salvar()
    cy.contains('Informe a competência').should('be.visible')
    for (const invalida of ['2026-1', 'abcd', '26-10']) {
      preencher({ competencia: invalida, ...valores })
      salvar()
      cy.contains('Use o formato AAAA-MM').should('be.visible')
    }
    cy.get('@lancar.all').should('have.length', 0)

    // Mês 13 passa pelo formato da tela; o servidor recusa e a tela mostra o motivo, sem linha nova.
    for (const invalida of ['2026-13', '2026-00']) {
      preencher({ competencia: invalida, ...valores })
      salvar()
      cy.wait('@lancar')
      cy.contains('mesReferencia deve estar no formato YYYY-MM.').should('be.visible')
      cy.contains('lançada').should('not.exist')
      cy.get('[data-cy="rentab-competencia"]').should('be.visible')
    }
    cy.get('[data-cy="rentab-linha"]').should('have.length', 1)

    // Competência já lançada: 409 explicado, linha original intacta.
    preencher({ competencia: '2026-08', ...valores })
    salvar()
    cy.wait('@lancar')
    cy.contains(
      'Já existe lançamento de rentabilidade para esta carteira nesta competência.',
    ).should('be.visible')
    cy.get('[data-cy="rentab-linha"]').should('have.length', 1)
    celulas().eq(1).should('have.text', '+2,00 %')

    // Cancelar não grava.
    cy.get('@lancar.all')
      .its('length')
      .then((antes) => {
        cy.contains('[role="dialog"] button', 'Cancelar').click()
        cy.get('[data-cy="rentab-competencia"]').should('not.exist')
        cy.get('@lancar.all').should('have.length', antes)
      })

    // Clique duplo em outra competência: um envio, uma linha.
    cy.get('@lancar.all')
      .its('length')
      .then((antes) => {
        abrirFormulario()
        preencher({ competencia: '2026-09', ...valores })
        cy.get('[data-cy="rentab-submit"]').dblclick()
        cy.contains('Rentabilidade de 2026-09 lançada').should('be.visible')
        cy.get('@lancar.all').should('have.length', antes + 1)
        cy.get('[data-cy="rentab-linha"]').should('have.length', 2)
      })
  })
})

export {}
